  return j.status === "printed"
    ? <div data-print-status="printed" style={{ fontSize: 13.5, fontWeight: 600, color: GREEN, marginTop: 6 }}>🖨 Label for {j.ref} printed{j.printedBy ? ` on ${j.printedBy}` : ""} {t(j.printedAt)} ✓</div>
    : <div data-print-status="waiting" style={{ fontSize: 13.5, fontWeight: 600, color: "#8A4B00", marginTop: 6 }}>🖨 Label for {j.ref} sent to the print station {t(j.requestedAt)} — waiting to print</div>;
