  const words = { photo: "Photo", pdf: "PDF", spreadsheet: "Spreadsheet" };
  const sub = (r) => `${words[r.kind] || "File"} · ${orderFileSize(r.bytes)}${r.original_bytes && r.original_bytes > (r.bytes || 0) * 1.5 ? ` (from ${orderFileSize(r.original_bytes)})` : ""} · kept ${plainDate(new Date(r.taken_at))}`;
