    const base = { position: "absolute", left, width, top: 10, bottom: 10, borderRadius: 8, boxSizing: "border-box", padding: wide ? "8px 10px" : "6px 4px", display: "flex", flexDirection: "column", justifyContent: "space-between", overflow: "hidden", minWidth: 6 };
    const st = bk.kind === "reel" ? { background: bk.ink[1], border: `2px solid ${bk.ink[0]}` } : bk.kind === "notrace" ? { background: "#fff", border: "2px dashed #B91C1C" }
      : bk.kind === "waiting" ? { background: "repeating-linear-gradient(135deg, #E8F3EC 0 10px, #F3FAF5 10px 20px)", border: "2px dashed #1E7F3C" } : { background: "repeating-linear-gradient(135deg, #FDE6D3 0 10px, #FBEBD9 10px 20px)", border: "2px solid #C2410C" };
    const title = bk.kind === "reel" || bk.kind === "notrace" ? bk.reel.batchNumber : bk.kind === "waiting" ? `${(bk.trace.stats && bk.trace.stats.traceNo) || "A trace"} waiting` : "On the line now";
