                  {lim && <><line x1={X0} x2={X1} y1={ty(lim.max)} y2={ty(lim.max)} stroke="#1E7F3C" strokeWidth="1.2" /><line x1={X0} x2={X1} y1={ty(lim.min)} y2={ty(lim.min)} stroke="#1E7F3C" strokeWidth="1.2" />
                    <line x1={X0} x2={X1} y1={ty(nomOf(lim))} y2={ty(nomOf(lim))} stroke="#1E7F3C" strokeDasharray="5 5" /></>}
                  {tTicks.map(tm => <line key={tm} x1={tx(tm)} x2={tx(tm)} y1={Y0} y2={Y1} stroke="#EEF1F5" strokeDasharray="3 4" />)}
