const PROVISIONAL_ORDERS_KEY = "mxProvisionalOrders";
function readProvisionalOrders() { try { const v = JSON.parse(localStorage.getItem(PROVISIONAL_ORDERS_KEY) || "[]"); return Array.isArray(v) ? v : []; } catch (e) { return []; } }
