  window.addEventListener("error", (e) => { const m = String((e && e.message) || "error"); if (once(m)) reportAppEvent({ kind: "error", message: m, detail: e && e.error && e.error.stack }); });
  window.addEventListener("unhandledrejection", (e) => { const m = String((e && e.reason && (e.reason.message || e.reason)) || "unhandled"); if (once(m)) reportAppEvent({ kind: "error", message: m, detail: e && e.reason && e.reason.stack }); });
