  const doneAll = ordered.filter(x => (x.packedOutside || (x.contributions || []).some(r => Number(r.qty) > 0))).every(x => Number(String(caseWeights[x.caseNum] ?? "").trim()) > 0 && !(queries[x.caseNum]));
