  const readingLeft = Object.values(reads).filter(r => r === "reading").length;
  const anyRead = Object.values(reads).some(r => r && r !== "reading");
  const autoReport = !!(finished && check && onCheckDone && anyRead && readingLeft === 0 && doneAll && !ordered.some(x => hasBoxes(x) && !reads[x.caseNum]));
  useEffect(() => { if (autoReport) onCheckDone(Object.fromEntries(Object.entries(reads).filter(([, r]) => r && r !== "reading"))); },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [autoReport]);
