  /* WEIGH & CHECK: the photo is kept at once and read in the background — the weight can be typed while it's read; the
     photo is saved with what was read. */
  /* on to the next case still wanting a photo (or the end) — after a photo, and after Skip (Chris, 17 Oct 2026, 22:16: "it moves
     it forward itself as each photo is taken thus only requiring a skip button") */
  const moveOnFrom = (cn) => { const left = (x) => x.caseNum !== cn && hasBoxes(x) && !reads[x.caseNum] && !["skip", "done", "kept"].includes(shot[x.caseNum]);
    const nx = ordered.find(x => left(x) && x.caseNum > cn) || ordered.find(left); if (nx) setAt(nx.caseNum); else setFinished(true); };
  const takeAndRead = (file, cn = n, advance = false) => { if (!file) return; nlHaptic && nlHaptic();
    setShot(s => ({ ...s, [cn]: "done" })); setReads(r => ({ ...r, [cn]: "reading" }));
    /* snap and on to the next case still wanting a photo; this one's read shows there as it comes back */
    if (advance) { setLastShot(cn); moveOnFrom(cn); }
    (async () => { let res; try { res = await readLabelsFromFile(file); } catch (e) { res = { error: String((e && e.message) || e) }; }
      setReads(r => ({ ...r, [cn]: res || { error: "No answer came back — try again." } }));
      const saved = await saveCasePhoto({ file, orderId, caseNum: cn, source: "case-check", result: res && !res.error ? { ...res, weigh: true } : { weigh: true } });
      const st = photoSaveState(saved); if (st !== "saved") setShot(s => ({ ...s, [cn]: st })); })(); };
