  const smallCaseSizes = order?.smallCaseSizes || {};
  const caseRemovals = order?.caseRemovals || {};  // { boxNumber: true } — taken out of its case via the override, not yet placed elsewhere
  const confirmedCases = order?.confirmedCases || {}; // { caseNum: true } — closed by the override; contents are exactly what was saved
