  const palletAssignments = new Proxy({}, { get: (_t, k) => (typeof k === "symbol" ? undefined : casePalletOf(caseRecords, order, k)), has: () => true, ownKeys: () => Object.keys(order?.palletAssignments || {}), getOwnPropertyDescriptor: () => ({ enumerable: true, configurable: true }) });
