/* Smart Formes is PX Plus with the names changed, and Ken is PX Plus geometry
   cut with K pins in two colours only — neither is a brochure range, so both
   show the range they are cloned from rather than a chart of their own. */
const PUBLISHED_ALIAS = { "Smart Formes": "PX Plus" };

const SIZING_STEPS = [
  ["Clean the plate", "Degrease and dry the cutting plate or counter jacket. Anything left on it will show up in the crease."],
  ["Cut to length", "Use a proper matrix cutter at 45 or 90 degrees. A clean end sits down flat."],
  ["Locate on the rule", "Push the locator bridge down over the creasing rule so the channel sits square."],
  ["Peel the backing", "Lift the fingerlift tape to expose the adhesive, keeping the strip in place."],
  ["Take an impression", "One cycle at normal pressure transfers the matrix onto the plate."],
  ["Remove the bridges", "Lift the locators out of the channel and you're ready to run."],
];

const NINE_FAULTS = [
  ["Crease cracks when it is folded", "The crease looks clean coming off the press and splits on the folder-gluer."],
  ["The crease bursts on the press", "Fibres split along the crease as it is cut, not later."],
  ["The matrix lifts off the plate", "It moves during the run, or comes away with the sheet."],
  ["Residue left behind at changeover", "The matrix comes up but the adhesive stays on the plate."],
  ["The matrix crushes or loses its profile", "Creases go shallow part-way through the run and the shoulders spread."],
  ["The crease is off-centre", "One shoulder is deeper than the other, and the carton folds skew."],
  ["Splitting at the corners of a crease", "The crease is sound along its length and fails where it meets another."],
  ["Angel hair and dusting", "Fine fibres around the cut edge, all over the sheet and into the machine."],
  ["Ejection rubber goes hard", "It worked when it went on and now it does not push the waste out."],
];

const ACCESSORIES = [
  { name: "Super Shim Plus", what: "Self-adhesive shim tape. 8.0mm wide on a 12mm fingerlift backing, hardened stainless steel so it will not compress in use.",
    rows: [["0.03mm - 30 microns", "8mm wide, 10 metre roll"], ["0.05mm - 50 microns", "8mm wide, 10 metre roll"], ["0.10mm - 100 microns", "8mm wide, 10 metre roll"]] },
  { name: "Profitape", what: "Colour-coded self-adhesive patching tape for precise cutting and foil embossing, translucent enough to see your lines through.",
    rows: [["Blue", "3mm or 6mm x 30 micron x 35m"], ["Red", "3mm or 6mm x 50 micron x 25m"], ["Yellow", "3mm or 6mm x 80 micron x 18m"]] },
];

const BASE_COLOURS = {
  pink: "#F3A9C0", blue: "#5B8FD1", white: "#FFFFFF", red: "#D0463B", silver: "#C9CBCC",
  yellow: "#F2CE45", orange: "#E8883A", mauve: "#B49AC8", green: "#5E9E6B", sky: "#8FC7E8",
  lime: "#C2D94B", buff: "#E3D3A8", violet: "#8E76B8", rose: "#EBA9B4", slate: "#7C8794",
  brown: "#8B6A4F", black: "#2A2A2A", cream: "#F0E6CE", grey: "#9A9A9A",
};

/* productFormsOf, productsMissingForm, productDescription and slugForProduct
   were declared a second time here, byte for byte the same as the copies above
   at 24630. Both were top-level, so the later pair won and the first pair was
   dead — including the comment calling productDescription "the one place this
   string is built", which was true of neither copy. Editing the first would
   have changed nothing, silently. The duplicates are removed; the originals
   stand. (13 Sep 2026 — found by static_audit, ERROR: duplicate-declaration.) */

/* 700px, the same line the pick flow draws: below it the screen is a phone
   held in one hand, above it a tablet or a desk. Watched rather than read
   once, because the app gets opened in portrait and turned. */
/* A PHONE ON ITS SIDE IS STILL A PHONE (Chris, 1 Oct 2026: "Goes into old mode when phone turns on its side"). Turned
   landscape an iPhone is 840-odd wide, past the 760 line, so the app dropped back to the desk layout. A phone is now a
   narrow screen OR a short one under a finger (landscape phone: under 500 high, touch) — a tablet or a PC is neither. */
function isPhoneScreen(bp = 760) {
  try { return window.innerWidth < bp || (window.innerHeight < 500 && window.matchMedia("(pointer: coarse)").matches); } catch (e) { return false; }
}
function useIsPhone(bp = 700) {
  const [phone, setPhone] = useState(() => typeof window !== "undefined" && isPhoneScreen(bp));
  useEffect(() => {
    const on = () => setPhone(isPhoneScreen(bp));
    window.addEventListener("resize", on);
    window.addEventListener("orientationchange", on);
    return () => { window.removeEventListener("resize", on); window.removeEventListener("orientationchange", on); };
  }, [bp]);
  return phone;
}

/* ---------------------------------------------------------------------
   THE PUBLISHED PAGES. Top-level components, not declared inside
   ProductsView — a component defined during render is a new type every
   render, which remounts everything under it. (See CustomerField.) */

function PublishedChart({ chart }) {
  const cell = { padding: "5px 8px", borderBottom: `1px solid ${BORDER}`, verticalAlign: "top" };
  return (
    <div style={{ marginBottom: 16 }}>
      <div style={{ fontWeight: 650, fontSize: 14, marginBottom: 4 }}>{chart.base}</div>
      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
          <thead>
            <tr style={{ textAlign: "left", color: INK_MUTED, fontSize: 11, letterSpacing: ".04em" }}>
              <th style={{ ...cell, width: 110 }}>BASE COLOUR</th>
              <th style={{ ...cell, width: 80 }}>HEIGHT</th>
              <th style={cell}>{chart.ruleCol ? "CHANNEL WIDTH" : "CHANNEL WIDTHS (MM)"}</th>
              {chart.ruleCol ? <th style={{ ...cell, width: 120 }}>RULE</th> : null}
            </tr>
          </thead>
          <tbody>
            {chart.rows.map((r, i) => {
              const swatch = BASE_COLOURS[String(r[0]).toLowerCase()];
              return (
                <tr key={i}>
                  <td style={cell}>
                    {swatch ? (
                      <span style={{ display: "inline-block", width: 10, height: 10, marginRight: 6,
                        borderRadius: 2, background: swatch, border: `1px solid ${BORDER}` }} />
                    ) : null}
                    {r[0]}
                  </td>
                  <td style={cell}>{/^[0-9.]+$/.test(r[1]) ? `${r[1]} mm` : r[1]}</td>
                  <td style={cell}>{r[2]}</td>
                  {chart.ruleCol ? <td style={cell}>{r[3]}</td> : null}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <div className="text-xs" style={{ color: INK_MUTED, marginTop: 4 }}>{chart.per}</div>
    </div>
  );
}

function PublishedRange({ range }) {
  const [open, setOpen] = useState(false);
  const key = PUBLISHED_ALIAS[range] || range;
  const pub = PUBLISHED[key];
  if (!pub) return null;
  const cloned = key !== range;
  return (
    <Panel className="p-4 mb-4">
      <button onClick={() => setOpen(!open)}
        style={{ all: "unset", cursor: "pointer", display: "block", width: "100%" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 10 }}>
          <div>
            <div style={{ fontSize: 16, fontWeight: 650 }}>From the brochure — {pub.title}</div>
            <div className="text-xs" style={{ color: INK_MUTED, marginTop: 2 }}>
              {cloned
                ? `${range} is ${pub.title} with the names changed, so the published chart is ${pub.title}'s.`
                : "The published range, as the technical guide issued 13 September 2026 has it."}
            </div>
          </div>
          <div className="text-xs" style={{ color: INK_MUTED, whiteSpace: "nowrap" }}>{open ? "hide" : "show"}</div>
        </div>
      </button>
      {open ? (
        <div style={{ marginTop: 14 }}>
          <div style={{ fontSize: 14, marginBottom: 12 }}>{pub.line}</div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 10, marginBottom: 16 }}>
            {pub.points.map(([h, b], i) => (
              <div key={i} style={{ flex: "1 1 210px", padding: "8px 10px", borderRadius: 4,
                background: "#F4F4F2", border: `1px solid ${BORDER}` }}>
                <div style={{ fontWeight: 650, fontSize: 13 }}>{h}</div>
                <div className="text-xs" style={{ color: INK_MUTED, marginTop: 2 }}>{b}</div>
              </div>
            ))}
          </div>
          {pub.charts.map((c, i) => <PublishedChart key={i} chart={c} />)}
          <div className="text-xs" style={{ color: INK_MUTED, borderTop: `1px solid ${BORDER}`, paddingTop: 8 }}>
            Sizes are a guide, not a specification — board behaves differently press to press.
            This is what the paper promises; what is on the shelf is the table above.
          </div>
        </div>
      ) : null}
    </Panel>
  );
}

