function nlDue(o) {
  if (!o.dueDate) return { text: "No date", tone: "plain" };
  const d = Math.round((Date.parse(String(o.dueDate).slice(0, 10) + "T12:00:00") - Date.parse(todayISO() + "T12:00:00")) / 86400000);
  if (d < 0) return { text: `${-d} day${d === -1 ? "" : "s"} late`, tone: "warn" };
  if (d === 0) return { text: "Today", tone: "warn" };
  if (d === 1) return { text: "Tomorrow", tone: "warn" };
  return { text: new Date(o.dueDate + "T12:00:00").toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short" }), tone: "plain" };
}
