  const swipeAction = onShip && done ? ["Ship", () => onShip(o.id)] : onPick && nx && /^Pick/.test(nx) ? ["Pick", () => onPick(o.id)] : null;
  /* the press (tap / hold) rides pointer events; the swipe rides touch events, so a finger moving sideways never opens the order */
