  const exceed = /^\s*exceed\b/i.test(s); const c = exceed ? null : productColourFor(s);
  const col = exceed ? "#FFFFFF" : (c && c.hex) || "#8A93A8"; const pale = /^#(F|E[89A-F]|C[4-9])/i.test(col);   /* Exceed rubber is WHITE (Chris, 3 Oct 2026) */
