    <defs><linearGradient id={`mf${u}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor={hi} /><stop offset="0.45" stopColor={col} /><stop offset="1" stopColor={lo} /></linearGradient></defs>
    {shapes.map((d, i) => <path key={"s" + i} d={d} transform="translate(0.35 0.9)" fill="#14213D" opacity="0.14" />)}
    {shapes.map((d, i) => <path key={"b" + i} d={d} fill={`url(#mf${u})`} stroke={edge} strokeWidth="0.55" strokeLinejoin="round" />)}
