          const rackAll = onRack && (Number(l.bond) || 0) >= (Number(l.make) || 0);
          const whyLoose = loose > 0 ? `${loose} not planned on any day yet${rackAll ? ` — the reels are on the rack (${l.bondReels.slice(0, 3).join(", ")}${l.bondReels.length > 3 ? " …" : ""})` : gi && gi.ready ? ` — the glue line plan has them ready ${dayShort(gi.ready)}` : onRack ? "" : " — and no glue planned for them yet"}` : "";
