    const fresh = planRowsForNewOrder(orderId, whole, { startingCaseNum: Number(ordRow.startingCaseNum) || 0, actor: currentActor(), data: prevData });
    cases = [...(prevData.cases || []).map(c => c && !c.deleted && c.orderId === orderId ? { ...c, deleted: true, deletedAt: now, updatedAt: now } : c), ...fresh];
