    if (lineItems.some(l => l && !l.deleted && l.orderId === orderId && l.id !== lineId && sameProductSpec(l.description, from)))
      return { refused: `There's another line of ${from} on this order, and its cases can't be told apart from this one's — ask admin to change it.` };
