      const keys = Object.keys(plan).filter(k => sameProductSpec(k, from)); if (!keys.length) return c;
      const np = {}; for (const [k, q] of Object.entries(plan)) { const kk = keys.includes(k) ? description : k; np[kk] = (Number(np[kk]) || 0) + (Number(q) || 0); }
