const NLA_RANGES = ["PX Plus", "PX", "Smart Formes", "Speedy Crease", "Speedy Crease Metal", "Ultra SR", "Phoenix XL", "Exceed", "Profile Tape", "Profitape", "Super Shim Plus"];   // shim + Profitape chips (19 Oct 2026)
const nlaWords = (s) => String(s || "").toLowerCase().replace(/×/g, " x ").replace(/(\d)\s*x\s*(\d)/g, "$1 x $2").replace(/(\d)mm\b/g, "$1 ").split(/\s+/).filter(w => w && w !== "x");
