      <span style={{ flex: 1, minWidth: 0 }}><span data-nl-line-name style={{ display: "block", fontSize: 17, fontWeight: 600, letterSpacing: -0.2, lineHeight: 1.25, color: NL.INK }}>{l.spec.replace(/\s*\(\d+m\)$/, "")}</span>
        {l.sample && <span data-nl-line-sample style={{ display: "block", fontSize: 12.5, color: NL.AMBERTXT, fontWeight: 700, marginTop: 1 }}>Sample · no commercial value</span>}
        {(l.ref || l.amendment) && <span style={{ display: "block", fontSize: 12.5, color: NL.SUB, marginTop: 1 }}>{[l.ref, l.amendment].filter(Boolean).join(" · ")}</span>}</span>
