    /* SOMEONE ELSE'S UNSENT CHANGES (third review item 4): they can only go up under the login that made them. Signing in as
       anybody else asks — throw them away, or stop so that person signs in first. Never sent under the wrong name. */
    { const owner = unsentOwner(), me = String(email || "").trim().toLowerCase(), n = unsentChangeCount();
      if (owner && me && owner !== me && n > 0) {
        const nm = (e) => { const x = String(e).split("@")[0]; return x.charAt(0).toUpperCase() + x.slice(1); };
        /* KEEP THEM FOR THEIR OWNER — asked first (Chris, 19 Oct 2026: "2-yes"; mx_sync.js parkUnsentRows/restoreParked) */
        const keep = typeof window !== "undefined" && window.confirm(`This device has ${n} change${n === 1 ? "" : "s"} made by ${nm(owner)} that haven't reached the cloud yet. Only ${nm(owner)} signing in here can send them.\n\nOK — keep them on this device for ${nm(owner)}. They go up the next time ${nm(owner)} signs in here.\nCancel — other choices.`);
        if (keep) { try { const pk = parkUnsentRows(pendingColumnsRef.current || {}, dataRef.current || {});
            const all = JSON.parse(localStorage.getItem(PARKED_UNSENT_KEY) || "{}"); all[owner] = mergeParked(all[owner], { owner, at: new Date().toISOString(), rows: pk.rows });
            localStorage.setItem(PARKED_UNSENT_KEY, JSON.stringify(all));
            reportAppEvent({ kind: "unsent_parked", message: `${n} unsent change${n === 1 ? "" : "s"} made by ${owner} kept on this device for ${owner} when ${me} signed in` });
          } catch (e) { console.error("Could not keep them aside:", e); } }
        const ok = keep || (typeof window !== "undefined" && window.confirm(`This device has ${n} change${n === 1 ? "" : "s"} made by ${nm(owner)} that haven't reached the cloud yet. Only ${nm(owner)} signing in here can send them.\n\nOK — throw ${nm(owner)}'s unsent changes away and sign in as ${nm(me)}.\nCancel — don't sign in, so ${nm(owner)} can sign in first and send them.`));
        if (!ok) { try { await client.auth.signOut(); } catch (e) { /* offline */ } throw new Error(`Not signed in — ${nm(owner)} has unsent changes on this device. ${nm(owner)} needs to sign in here first.`); }
        /* thrown away means the cloud's copy of each of those rows comes back here too (below), and a delete that was owed is
           no longer kept out of the merge */
        for (const [t, m] of Object.entries(pendingColumnsRef.current || {})) discardedRows[t] = Object.keys(m || {});
        for (const id of Object.keys(deletionTimesRef.current || {})) pendingDeletionsRef.current.delete(id);
        savePendingDeletions(pendingDeletionsRef.current);
        pendingColumnsRef.current = {}; savePendingColumns({}); deletionTimesRef.current = {}; saveDeletionTimes({});
        try { localStorage.removeItem(UNSENT_OWNER_KEY); } catch (e) { /* private mode */ }
        if (!keep) reportAppEvent({ kind: "unsent_discarded", message: `${n} unsent change${n === 1 ? "" : "s"} made by ${owner} on this device thrown away when ${me} signed in` });
      } }
    /* the owner is back: their parked changes go back through the ordinary save once this sign-in has settled */
    { const me2 = String(email || "").trim().toLowerCase(); let has = false; try { has = !!(JSON.parse(localStorage.getItem(PARKED_UNSENT_KEY) || "{}")[me2]); } catch (e) {}
      if (has) setTimeout(() => { try { window.dispatchEvent(new CustomEvent("mx-restore-parked", { detail: me2 })); } catch (e) {} }, 4000); }
    const connectRes = await fetchRemoteTables(client); // full, deliberately — see fetchRemoteTables
