    try { const was = String(localStorage.getItem("matrixSyncEmail") || "").toLowerCase(); if (was && was !== String(email || "").toLowerCase()) setCurrentOperator(""); } catch (e) { /* private mode */ }
    localStorage.setItem("matrixSyncEmail", email);
